"use client";

import {
  RiAddLine,
  RiCloseLine,
  RiFilter3Fill,
  RiGroupLine,
  RiHomeLine,
  RiMenuLine,
} from "@remixicon/react";
import { type ComponentType, type ReactNode, useEffect, useRef, useState } from "react";
import { Avatar } from "../../base/avatar/avatar";
import { Breadcrumb, BreadcrumbItem } from "../../base/breadcrumb/breadcrumb";
import { Button } from "../../base/buttons/button";
import { IconButton } from "../../base/buttons/icon-button";
import { cx } from "@/lib/cx";
import { NotificationBell } from "../app-shell/notification-bell";
import { DASHBOARD_NAV, DashboardSidebar } from "../dashboard/dashboard-sidebar";

export interface TemplateShellProps {
  title: string;
  heading?: string;
  selected?: string;
  action?: string;
  onAction?: () => void;
  actions?: ReactNode;
  children: ReactNode;
  contained?: boolean;
  className?: string;
  columnClassName?: string;
  hideHeader?: boolean;
  icon?: ComponentType<{ className?: string; "aria-hidden"?: boolean | "true" | "false" }>;
}

/** The floating navigation and 1300px content column shared by dashboard templates. */
export function TemplateShell({
  title,
  heading = title,
  selected = "home",
  action = "Create ticket",
  onAction,
  actions,
  children,
  contained,
  className,
  columnClassName,
  hideHeader,
  icon: Icon = RiHomeLine,
}: TemplateShellProps) {
  const [navOpen, setNavOpen] = useState(false);
  const [filtersOpen, setFiltersOpen] = useState(false);
  const closeRef = useRef<HTMLButtonElement>(null);
  useEffect(() => {
    if (!navOpen) return;
    closeRef.current?.focus();
    const close = (event: KeyboardEvent) => {
      if (event.key === "Escape") setNavOpen(false);
    };
    window.addEventListener("keydown", close);
    return () => window.removeEventListener("keydown", close);
  }, [navOpen]);
  const nav = [
    ...DASHBOARD_NAV,
    // The library intentionally adds its HR template to the reference navigation.
    { key: "hr", label: "HR Team", icon: RiGroupLine, href: "/templates/hr" },
  ];
  return (
    <div
      className={cx(
        "relative flex w-full bg-background-full",
        contained ? "h-full min-h-[600px] overflow-hidden" : "min-h-dvh",
        className,
      )}
    >
      <div
        className={cx(
          "hidden shrink-0 py-3 pl-3 lg:block",
          contained ? "h-full" : "sticky top-0 h-dvh",
        )}
      >
        <DashboardSidebar items={nav} selected={selected} />
      </div>
      {navOpen && (
        <div className={cx("inset-0 z-40 lg:hidden", contained ? "absolute" : "fixed")}>
          <button
            type="button"
            aria-label="Close navigation overlay"
            onClick={() => setNavOpen(false)}
            className="absolute inset-0 bg-background-modal-overlay backdrop-blur-sm"
          />
          <div className="relative h-full w-[284px] p-3">
            <DashboardSidebar
              mobile
              items={nav}
              selected={selected}
              onClose={() => setNavOpen(false)}
            />
          </div>
          <button
            type="button"
            ref={closeRef}
            onClick={() => setNavOpen(false)}
            aria-label="Close navigation"
            className="absolute top-5 left-[290px] rounded-full bg-background-primary-default p-2 text-text-primary"
          >
            <RiCloseLine className="size-5" />
          </button>
        </div>
      )}
      <main
        className={cx(
          "relative flex min-w-0 flex-1 justify-center bg-background-full p-3 sm:pt-6",
          contained && "overflow-y-auto",
        )}
      >
        <div className={cx("flex w-full max-w-[1300px] flex-col gap-4 pb-4", columnClassName)}>
          {/* The header has a 10px following gap; content rows remain 16px apart. */}
          {!hideHeader && (
            <header className="-mb-1.5 flex w-full flex-col gap-2">
              <Breadcrumb>
                <BreadcrumbItem href="/templates/dashboard">
                  <Avatar size="xs" color="blue" initials="B" />
                  Board team
                </BreadcrumbItem>
                <BreadcrumbItem href="/templates/ai-profile">
                  <Avatar size="xs" initials="M" />
                  Mertcan
                </BreadcrumbItem>
                <BreadcrumbItem current icon={Icon}>
                  {title}
                </BreadcrumbItem>
              </Breadcrumb>
              <div className="flex w-full flex-wrap items-end justify-between gap-2">
                <div className="flex min-w-0 items-center gap-1.5">
                  <IconButton
                    icon={RiMenuLine}
                    className="lg:hidden"
                    aria-label="Open navigation"
                    onClick={() => setNavOpen(true)}
                  />
                  <h1 className="px-1 text-title-2-medium text-text-primary">{heading}</h1>
                </div>
                <div className="flex flex-wrap items-center justify-end gap-2.5">
                  {actions !== undefined ? (
                    actions
                  ) : (
                    <>
                      <NotificationBell />
                      <Button
                        variant="secondary"
                        leadingIcon={RiFilter3Fill}
                        onClick={() => setFiltersOpen((open) => !open)}
                        aria-expanded={filtersOpen}
                      >
                        Filters
                      </Button>
                      {onAction && (
                        <Button leadingIcon={RiAddLine} onClick={onAction}>
                          {action}
                        </Button>
                      )}
                    </>
                  )}
                </div>
              </div>
              {filtersOpen && (
                <div className="flex items-center justify-between gap-3 rounded-xl bg-background-secondary-default px-4 py-3 text-body-regular text-text-secondary">
                  <span>
                    Use each chart’s period menu and the table filters below to explore this view.
                  </span>
                  <Button
                    size="small"
                    variant="secondary"
                    onClick={() => {
                      document
                        .querySelector("main section:last-child")
                        ?.scrollIntoView({ behavior: "smooth" });
                      setFiltersOpen(false);
                    }}
                  >
                    Go to records
                  </Button>
                </div>
              )}
            </header>
          )}
          {hideHeader && (
            <div className="lg:hidden">
              <IconButton
                icon={RiMenuLine}
                aria-label="Open navigation"
                onClick={() => setNavOpen(true)}
              />
            </div>
          )}
          {children}
        </div>
      </main>
    </div>
  );
}

"use client";

import {
  RiDeleteBin6Line,
  RiDownload2Line,
  RiEditLine,
  RiMore2Fill,
  RiSearchLine,
} from "@remixicon/react";
import { useMemo, useState } from "react";
import { Dialog, Heading, Modal, ModalOverlay, type SortDescriptor } from "react-aria-components";
import { Avatar } from "../../base/avatar/avatar";
import { Chip } from "../../base/badges/chip";
import { Button } from "../../base/buttons/button";
import {
  Dropdown,
  DropdownItem,
  DropdownPopover,
  DropdownTrigger,
} from "../../base/dropdown/dropdown";
import { Input, InputBase } from "../../base/input/input";
import { Pagination } from "../../base/pagination/pagination";
import { Select, SelectItem } from "../../base/select/select";
import {
  Table,
  TableBody,
  TableCell,
  TableColumn,
  TableHeader,
  TableRow,
} from "../../base/table/table";
import { cx } from "@/lib/cx";
import { TEMPLATE_DEMO_ROWS } from "./table-demo-data";

export type TemplateTableKind = "finance" | "marketing" | "hr" | "medical";
export interface TemplateRow {
  id: string;
  name: string;
  subtitle?: string;
  avatar?: string;
  status: string;
  category: string;
  date: string;
  amount?: number;
  account?: string;
  tags?: string[];
}
const config = {
  finance: {
    noun: "transactions",
    name: "Transaction",
    status: "Account",
    category: "Category",
    date: "Date",
    amount: "Amount",
    statuses: ["Checking", "Savings", "Credit card"],
  },
  marketing: {
    noun: "campaigns",
    name: "Campaign",
    status: "Delivery",
    category: "Objective",
    date: "Last updated",
    amount: "Spend",
    statuses: ["Active", "Paused", "Draft"],
  },
  hr: {
    noun: "employees",
    name: "Employee",
    status: "Status",
    category: "Department",
    date: "Start date",
    amount: "Salary",
    statuses: ["Active", "On leave", "Contract"],
  },
  medical: {
    noun: "patients",
    name: "Patient",
    status: "Admission",
    category: "Status",
    date: "Next appointment",
    amount: "Condition",
    statuses: ["Inpatient", "Outpatient", "Discharged", "Emergency"],
  },
} as const;

/** Public example data; pass rows from your application for live records. */
export function createTemplateRows(kind: TemplateTableKind): TemplateRow[] {
  return TEMPLATE_DEMO_ROWS[kind].map((row) => ({
    ...row,
    ...(row.tags ? { tags: [...row.tags] } : {}),
  }));
}

export function TemplateRecordDialog({
  kind,
  row,
  onSave,
  onClose,
}: {
  kind: TemplateTableKind;
  row: TemplateRow;
  onSave: (row: TemplateRow) => void;
  onClose: () => void;
}) {
  const [draft, setDraft] = useState(row);
  const cfg = config[kind];
  return (
    <ModalOverlay
      isOpen
      onOpenChange={(open) => !open && onClose()}
      isDismissable
      className="fixed inset-0 z-50 flex items-center justify-center bg-background-modal-overlay p-4 backdrop-blur-sm"
    >
      <Modal className="w-full max-w-md rounded-3xl border border-border-button-default bg-background-primary-default p-6 shadow-dropdown">
        <Dialog className="outline-none">
          <form
            onSubmit={(event) => {
              event.preventDefault();
              if (draft.name.trim()) onSave({ ...draft, name: draft.name.trim() });
            }}
            className="flex flex-col gap-4"
          >
            <Heading slot="title" className="text-title-3-medium text-text-primary">
              {row.name ? "Edit" : "Add"} {cfg.name.toLowerCase()}
            </Heading>
            <Input
              label={cfg.name}
              value={draft.name}
              onChange={(name) => setDraft({ ...draft, name })}
              isRequired
              autoFocus
            />
            <Input
              label={cfg.category}
              value={draft.category}
              onChange={(category) => setDraft({ ...draft, category })}
            />
            <Input
              label={cfg.date}
              type="date"
              value={draft.date}
              onChange={(date) => setDraft({ ...draft, date })}
            />
            {kind !== "medical" && (
              <Input
                label={cfg.amount}
                type="number"
                value={String(draft.amount ?? 0)}
                onChange={(value) => setDraft({ ...draft, amount: Number(value) })}
              />
            )}
            <Select
              aria-label={cfg.status}
              selectedKey={draft.status}
              onSelectionChange={(key) => setDraft({ ...draft, status: String(key) })}
            >
              {cfg.statuses.map((status) => (
                <SelectItem id={status} key={status} textValue={status}>
                  {status}
                </SelectItem>
              ))}
            </Select>
            <div className="flex justify-end gap-2 pt-2">
              <Button variant="secondary" onClick={onClose}>
                Cancel
              </Button>
              <Button type="submit">Save changes</Button>
            </div>
          </form>
        </Dialog>
      </Modal>
    </ModalOverlay>
  );
}

export function TemplateTable({
  kind,
  rows: suppliedRows,
  onRowsChange,
  pageSize = 10,
  className,
}: {
  kind: TemplateTableKind;
  rows?: TemplateRow[];
  onRowsChange?: (rows: TemplateRow[]) => void;
  pageSize?: number;
  className?: string;
}) {
  const defaults = useMemo(() => createTemplateRows(kind), [kind]);
  const [edits, setEdits] = useState<Record<string, TemplateRow>>({});
  const [deleted, setDeleted] = useState<string[]>([]);
  const [editing, setEditing] = useState<TemplateRow | null>(null);
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState("all");
  const [status, setStatus] = useState("all");
  const [amount, setAmount] = useState("all");
  const [page, setPage] = useState(1);
  const [sort, setSort] = useState<SortDescriptor>({ column: "", direction: "ascending" });
  const cfg = config[kind];
  const rows = (suppliedRows ?? defaults)
    .filter((row) => !deleted.includes(row.id))
    .map((row) => edits[row.id] ?? row);
  const filtered = rows
    .filter(
      (row) =>
        (category === "all" || row.category === category) &&
        (status === "all" || row.status === status) &&
        (amount === "all" ||
          (amount === "income"
            ? (row.amount ?? 0) > 0
            : amount === "under"
              ? Math.abs(row.amount ?? 0) < (kind === "hr" ? 90000 : 500)
              : Math.abs(row.amount ?? 0) >= (kind === "hr" ? 90000 : 500))) &&
        [row.name, row.subtitle, row.category, row.status, row.date, ...(row.tags ?? [])]
          .join(" ")
          .toLowerCase()
          .includes(query.trim().toLowerCase()),
    )
    .sort((a, b) => {
      const key = sort.column as keyof TemplateRow;
      const av = a[key],
        bv = b[key];
      const result =
        typeof av === "number" && typeof bv === "number"
          ? av - bv
          : String(av ?? "").localeCompare(String(bv ?? ""));
      return sort.direction === "descending" ? -result : result;
    });
  const pages = Math.max(1, Math.ceil(filtered.length / Math.max(1, pageSize)));
  const current = Math.min(page, pages);
  const visible = filtered.slice((current - 1) * pageSize, current * pageSize);
  const update = (next: TemplateRow) => {
    setEdits((old) => ({ ...old, [next.id]: next }));
    onRowsChange?.(rows.map((row) => (row.id === next.id ? next : row)));
  };
  const remove = (id: string) => {
    setDeleted((old) => [...old, id]);
    onRowsChange?.(rows.filter((row) => row.id !== id));
  };
  const exportCsv = () => {
    const csv = [
      [cfg.name, cfg.status, cfg.category, cfg.date, cfg.amount],
      ...filtered.map((row) => [
        row.name,
        row.status,
        row.category,
        row.date,
        row.amount ?? row.tags?.join("; "),
      ]),
    ]
      .map((row) => row.map((value) => `"${String(value ?? "").replaceAll('"', '""')}"`).join(","))
      .join("\n");
    const url = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
    const link = document.createElement("a");
    link.href = url;
    link.download = `${cfg.noun}.csv`;
    link.click();
    setTimeout(() => URL.revokeObjectURL(url), 0);
  };
  return (
    <section
      className={cx(
        "flex w-full min-w-0 flex-col gap-3 rounded-2xl bg-background-secondary-default p-2",
        className,
      )}
    >
      <div className="flex flex-col gap-3 px-3 py-1 sm:flex-row sm:items-center sm:justify-between">
        <div className="shrink-0">
          <p className="text-body-medium text-text-tertiary">Total Results</p>
          <p className="text-body-medium text-text-primary">
            {filtered.length.toLocaleString()} {cfg.noun}
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-2.5">
          <Select
            aria-label={`Filter ${cfg.status.toLowerCase()}`}
            selectedKey={status}
            onSelectionChange={(key) => {
              setStatus(String(key));
              setPage(1);
            }}
          >
            <SelectItem id="all">All {kind === "finance" ? "accounts" : "statuses"}</SelectItem>
            {cfg.statuses.map((s) => (
              <SelectItem key={s} id={s}>
                {s}
              </SelectItem>
            ))}
          </Select>
          <Select
            aria-label={`Filter ${cfg.category.toLowerCase()}`}
            selectedKey={category}
            onSelectionChange={(key) => {
              setCategory(String(key));
              setPage(1);
            }}
          >
            <SelectItem id="all">
              All{" "}
              {kind === "hr" ? "departments" : kind === "marketing" ? "objectives" : "categories"}
            </SelectItem>
            {[...new Set(rows.map((row) => row.category))].sort().map((s) => (
              <SelectItem key={s} id={s}>
                {s}
              </SelectItem>
            ))}
          </Select>
          {kind !== "medical" && (
            <Select
              aria-label={`Filter ${cfg.amount.toLowerCase()}`}
              selectedKey={amount}
              onSelectionChange={(key) => {
                setAmount(String(key));
                setPage(1);
              }}
            >
              <SelectItem id="all">All {kind === "hr" ? "salaries" : "amounts"}</SelectItem>
              <SelectItem id="under">{kind === "hr" ? "Under $90K" : "Under $500"}</SelectItem>
              <SelectItem id="over">
                {kind === "hr" ? "$90K and above" : "$500 and above"}
              </SelectItem>
              {kind === "finance" && <SelectItem id="income">Income only</SelectItem>}
            </Select>
          )}
          <InputBase
            aria-label={`Search ${cfg.noun}`}
            placeholder="Search"
            leadingIcon={RiSearchLine}
            value={query}
            onChange={(event) => {
              setQuery(event.target.value);
              setPage(1);
            }}
            className="w-40"
          />
          <Button
            variant="secondary"
            iconOnly
            leadingIcon={RiDownload2Line}
            aria-label={`Export ${cfg.noun}`}
            onClick={exportCsv}
          />
        </div>
      </div>
      <Table aria-label={cfg.noun} sortDescriptor={sort} onSortChange={setSort}>
        <TableHeader>
          <TableColumn id="name" isRowHeader allowsSorting>
            {cfg.name}
          </TableColumn>
          <TableColumn id="status" allowsSorting>
            {cfg.status}
          </TableColumn>
          <TableColumn id="category" allowsSorting>
            {cfg.category}
          </TableColumn>
          <TableColumn id="date" allowsSorting>
            {cfg.date}
          </TableColumn>
          <TableColumn id="amount" allowsSorting={kind !== "medical"}>
            {cfg.amount}
          </TableColumn>
          <TableColumn id="actions">Actions</TableColumn>
        </TableHeader>
        <TableBody
          items={visible}
          renderEmptyState={() => (
            <p className="py-12 text-center text-body-regular text-text-secondary">
              No {cfg.noun} match your filters.
            </p>
          )}
        >
          {(row) => (
            <TableRow id={row.id} key={row.id}>
              <TableCell>
                <div className="flex items-center gap-2.5">
                  {(kind === "hr" || kind === "medical") && (
                    <Avatar
                      size="xs"
                      src={row.avatar}
                      initials={row.name
                        .split(" ")
                        .map((s) => s[0])
                        .slice(0, 2)
                        .join("")}
                      alt={row.name}
                    />
                  )}
                  <div>
                    <p className="text-body-medium text-text-primary">{row.name}</p>
                    {row.subtitle && (
                      <p className="text-body-2-regular text-text-tertiary">{row.subtitle}</p>
                    )}
                  </div>
                </div>
              </TableCell>
              <TableCell>
                <Select
                  aria-label={`${cfg.status} for ${row.name}`}
                  size="sm"
                  selectedKey={row.status}
                  onSelectionChange={(key) => update({ ...row, status: String(key) })}
                >
                  {cfg.statuses.map((s) => (
                    <SelectItem id={s} key={s}>
                      {s}
                    </SelectItem>
                  ))}
                </Select>
              </TableCell>
              <TableCell>
                <Chip
                  color={
                    row.category === "Critical"
                      ? "rose"
                      : row.category === "Stable"
                        ? "lime"
                        : "neutral"
                  }
                >
                  {row.category}
                </Chip>
              </TableCell>
              <TableCell>
                <span className="whitespace-nowrap text-text-secondary">
                  {new Date(`${row.date}T12:00:00Z`).toLocaleDateString("en-US", {
                    month: "short",
                    day: "2-digit",
                    year: "numeric",
                    timeZone: "UTC",
                  })}
                </span>
              </TableCell>
              <TableCell>
                {kind === "medical" ? (
                  <div className="flex gap-1">
                    {row.tags?.map((tag) => (
                      <Chip color="neutral" key={tag}>
                        {tag}
                      </Chip>
                    ))}
                  </div>
                ) : (
                  <span
                    className={cx(
                      "whitespace-nowrap text-body-medium tabular-nums",
                      kind === "finance" && (row.amount ?? 0) > 0
                        ? "text-status-lime-text"
                        : "text-text-primary",
                    )}
                  >
                    {kind === "finance" && (row.amount ?? 0) > 0 ? "+" : ""}
                    {(row.amount ?? 0).toLocaleString("en-US", {
                      style: "currency",
                      currency: "USD",
                      maximumFractionDigits: 0,
                      ...(kind === "hr" ? { notation: "compact" as const } : {}),
                    })}
                  </span>
                )}
              </TableCell>
              <TableCell>
                <Dropdown>
                  <DropdownTrigger
                    aria-label={`Actions for ${row.name}`}
                    className="flex size-8 cursor-pointer items-center justify-center rounded-lg text-foreground-icon-secondary hover:bg-background-secondary-hover"
                  >
                    <RiMore2Fill className="size-5" />
                  </DropdownTrigger>
                  <DropdownPopover aria-label={`Record actions for ${row.name}`}>
                    <DropdownItem onSelect={() => setEditing(row)}>
                      <RiEditLine className="size-4" />
                      Edit record
                    </DropdownItem>
                    <DropdownItem onSelect={() => remove(row.id)}>
                      <RiDeleteBin6Line className="size-4" />
                      Delete record
                    </DropdownItem>
                  </DropdownPopover>
                </Dropdown>
              </TableCell>
            </TableRow>
          )}
        </TableBody>
      </Table>
      <Pagination page={current} totalPages={pages} onChange={setPage} className="px-2 pt-1 pb-2" />
      {editing && (
        <TemplateRecordDialog
          kind={kind}
          row={editing}
          onClose={() => setEditing(null)}
          onSave={(row) => {
            update(row);
            setEditing(null);
          }}
        />
      )}
    </section>
  );
}

"use client";

import { useReducedMotion } from "motion/react";
import { useSyncExternalStore } from "react";

const subscribe = () => () => {};
const clientSnapshot = () => true;
const serverSnapshot = () => false;

/** Keep the first server/client render identical, then apply the user's motion preference. */
export function useHydratedReducedMotion(): boolean {
  const reduced = useReducedMotion();
  const hydrated = useSyncExternalStore(subscribe, clientSnapshot, serverSnapshot);
  return hydrated && reduced === true;
}
